import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Большинство компрессоров предлагают фиксированные размеры: 50, 100, 200 или 500 КБ. Но что делать, если портал требует 80 КБ, 150 КБ или 1,5 МБ?</p>\n<p>Этим занимается компрессор до точного размера файла. Вы вводите любое нужное значение, и инструмент сжимает изображение ровно под это число.</p>\n<p>Это руководство объясняет, как работает точный размер, когда его использовать и как избежать типичных ошибок с единицами измерения. Попробовать любой лимит на своём файле можно в инструменте <a href=\"/ru/szhat-izobrazhenie-do-tselego-razmera/\">Компрессор целевого размера файла</a> — просто введите нужное число в КБ или МБ.</p>\n<h2 id=\"what-is-target-compression\">Что такое сжатие до точного размера</h2>\n<p>Сжатие до точного размера — это когда вы сами задаёте цель. Вместо фиксированных 50 или 100 КБ вы вводите любое число: 80 КБ, 150 КБ, 1,5 МБ.</p>\n<p>Инструмент использует тот же бинарный поиск качества, что и инструменты с фиксированным размером. Он проверяет уровни качества, пока не найдёт самый высокий, который укладывается в ваше число.</p>\n<p>Вы можете ввести 80 КБ для портала с необычным лимитом или 300 КБ для темы блога с конкретным бюджетом. Подходит любое число.</p>\n<p>Это самый гибкий инструмент в наборе: один инструмент заменяет все фиксированные размеры, когда лимит нестандартный.</p>\n<h2 id=\"how-it-works\">Как это работает</h2>\n<p>Введите целевой размер в поле ввода и выберите КБ или МБ. Инструмент автоматически пересчитывает единицы при переключении.</p>\n<p>Загрузите изображение. Принимаются JPG, PNG, WebP и HEIC размером до 25 МБ.</p>\n<p>Инструмент запускает бинарный поиск качества и показывает результат. Ищите подтверждение, что файл оказался ниже вашей цели.</p>\n<p>Просмотрите результат перед скачиванием. Размер файла может быть правильным, а сама картинка — повреждённой.</p>\n<p>Если цель не достигнута, смените формат или разрешите масштабирование размеров, а затем запустите снова.</p>\n<h2 id=\"kb-vs-mb\">Килобайты против мегабайт</h2>\n<p>Килобайты подходят для маленьких целей. Лимиты порталов обычно указывают в КБ — например, 80 или 150 КБ, поэтому вводите число точно так, как указывает портал.</p>\n<p>Мегабайты подходят для больших целей. Цель 1,5 или 2 МБ проще вводить и читать в мегабайтах, чем как 1536 или 2048 КБ.</p>\n<p>Переключение единиц пересчитывает число за вас. Ввод 1 МБ и переключение на КБ покажет 1024 КБ, сохраняя цель неизменной.</p>\n<p>Когда сомневаетесь, вводите число в той единице, которую использует портал. Совпадение со словами портала предотвращает ошибки конвертации.</p>\n<p>Помните: 1 МБ равен 1024 КБ, а не 1000 КБ. Инструмент использует двоичное определение, которое совпадает с тем, как операционные системы измеряют файлы.</p>\n<h2 id=\"when-to-use-custom\">Когда использовать нестандартный размер</h2>\n<p>Когда портал требует необычное число: 80 КБ, 75 КБ, 150 КБ. Фиксированные инструменты здесь не помогут.</p>\n<p>Когда тема блога задаёт конкретный бюджет: например, 300 КБ на изображение. Точный размер держит все изображения в бюджете.</p>\n<p>Когда вложения в письмо должны уместиться в общий лимит. Набор изображений, который должен весить меньше 5 МБ, точно настраивается нестандартными целями.</p>\n<p>Когда типография или клиент называет точный максимальный вес для загрузки. Нестандартная цель попадает в число ровно, без угадывания.</p>\n<p>Во всех остальных случаях фиксированные инструменты проще: они уже настроены под самые частые лимиты.</p>\n<h2 id=\"binary-search-explained\">Бинарный поиск: объяснение</h2>\n<p>Инструмент не угадывает число качества. Он ищет лучшее, проверяя уровни качества и сужая диапазон при каждой проверке.</p>\n<p>Представьте, что вы угадываете число от 1 до 100. Каждая проверка делит оставшийся диапазон пополам, поэтому поиск сходится за несколько шагов.</p>\n<p>Поиск начинается с середины: он проверяет качество 50 и смотрит, укладывается ли результат в цель. Затем он движется вверх или вниз.</p>\n<p>За семь проверок поиск находит лучшее качество для вашего изображения. Найти качество 65 перебором от 100 заняло бы 35 проверок, а бинарный поиск находит его за семь.</p>\n<p>Каждая проверка — это перекодирование изображения, которое занимает реальное время. Тридцать пять перекодировок ощущаются медленными, а семь — мгновенными.</p>\n<h2 id=\"dimension-scaling\">Масштабирование размеров</h2>\n<p>Инструмент сначала пробует качество при полном размере. Размеры уменьшаются, только когда одного качества недостаточно.</p>\n<p>Масштабирование происходит маленькими шагами, а не одним прыжком. Инструмент проверяет масштабы вроде 90 и 80 процентов, останавливаясь на первом, который подходит.</p>\n<p>Небольшой шаг обычно незаметен. Фото шириной 1200 пикселей выглядит так же при ширине 1080 пикселей на экране.</p>\n<p>Размеры можно зафиксировать, если портал требует точные пиксели. Тогда инструмент работает только с качеством и честно предупредит, если цель недостижима.</p>\n<p>Для текста размеры важнее качества. Уменьшение документа делает буквы мельче, поэтому при важности текста предпочитайте снижение качества.</p>\n<h2 id=\"impossible-targets\">Невозможные цели</h2>\n<p>Некоторые цели недостижимы без потери смысла изображения. Плотное групповое фото с двадцатью лицами нельзя довести до 20 КБ и сохранить лица.</p>\n<p>Невозможные цели часто возникают из-за недоразумения. Портал, просящий 2 МБ, могли прочитать как 2 КБ — в тысячу раз меньше.</p>\n<p>Проверьте единицы измерения, когда цель кажется невозможной. Ошибка в единице — самая частая причина недостижимых целей.</p>\n<p>Фиксированные размеры тоже усложняют задачу. Если портал требует большой размер в пикселях и крошечный вес, эти правила могут противоречить друг другу.</p>\n<p>В таких случаях меняйте то, что можете контролировать: формат, обрезку, размеры. Если ничего не помогает, перечитайте правила портала.</p>\n<h2 id=\"formats-custom\">Форматы для нестандартных целей</h2>\n<p>JPG — безопасный выбор для фото при любой цели. Его принимают везде, и он хорошо справляется с плавными тонами.</p>\n<p>WebP часто чуть чище JPG при том же весе. Для нестандартных целей это преимущество может решить, достигнута цель или нет.</p>\n<p>PNG подходит для графики с плоскими цветами и прозрачностью. Для фото PNG тратит бюджет впустую и часто не достигает цели.</p>\n<p>Формат влияет на поиск: PNG при качестве 90 может весить больше, чем JPG при качестве 50. Поэтому поиск выполняется отдельно для каждого формата.</p>\n<p>Когда сомневаетесь, попробуйте оба формата. Один тест стоит больше десяти догадок.</p>\n<h2 id=\"batch-custom\">Пакетный режим с нестандартной целью</h2>\n<p>Пакетный режим сжимает много изображений до одной нестандартной цели сразу. Перетащите папку, введите цель — и пусть инструмент работает.</p>\n<p>Каждое изображение обрабатывается отдельно: бинарный поиск находит лучшее качество для каждого файла.</p>\n<p>Результаты скачиваются вместе архивом ZIP. Так набор фото товаров или миниатюр остаётся организованным в одном месте.</p>\n<p>Проверьте несколько результатов перед скачиванием всего архива. Если одно изображение выглядит мягким, запустите его отдельно.</p>\n<p>Держите цель одинаковой для всей партии. Смешанные цели дают смешанные результаты, которые на сайте выглядят неряшливо.</p>\n<h2 id=\"common-mistakes\">Типичные ошибки</h2>\n<p>Самая частая ошибка — неправильная единица измерения. Цель 100 МБ вместо 100 КБ даёт файл в тысячу раз больше нужного.</p>\n<p>Вторая ошибка — начинать с уже сжатого файла. Каждый круг добавляет повреждения, поэтому всегда используйте оригинал.</p>\n<p>Третья ошибка — закреплять PNG для фотографии. PNG не может чисто достичь цели для детальных фото.</p>\n<p>Четвёртая ошибка — забывать проверять результат. Вес файла может быть правильным, а изображение — размытым.</p>\n<p>И наконец, не удаляйте оригиналы после успеха. Правила меняются, и свежая копия с оригинала делается за минуту.</p>\n<h2 id=\"privacy-custom\">Конфиденциальность</h2>\n<p>Сжатие полностью происходит в вашем браузере. Ваше фото никогда не загружается на сервер, даже когда цель нестандартная.</p>\n<p>Инструмент также удаляет скрытые метаданные, включая GPS-метки. Это важно, когда файл — фото документа или личное фото.</p>\n<p>Для документов, удостоверяющих личность, удаление метаданных обязательно. В фото не должно быть данных о вашем телефоне или доме.</p>\n<p>Проверьте один файл после сжатия на метаданные. Убедитесь, что GPS-метки действительно удалены.</p>\n<p>Работайте в приватном окне, если компьютер общий. Так файлы и история не останутся в браузере после вас.</p>\n<h2 id=\"unit-mistakes\">Ошибки с единицами измерения</h2>\n<p>Самая дорогая ошибка в нестандартном сжатии — ошибка единицы. Ввод 100 МБ вместо 100 КБ даёт цель в тысячу раз больше нужной.</p>\n<p>Всегда читайте лимит портала дважды. Запишите число и единицу отдельно, а затем введите их отдельно в инструмент.</p>\n<p>Помните: 1 МБ равен 1024 КБ, а не 1000 КБ. Инструмент использует двоичное определение, которое совпадает с измерениями операционных систем.</p>\n<p>Когда портал пишет «2 МБ», введите 2 и выберите МБ. Не переводите в килобайты вручную — пусть это сделает инструмент.</p>\n<p>Проверьте результат после скачивания: вес файла должен быть чуть ниже вашей цели, а не в тысячу раз больше.</p>\n<h2 id=\"target-for-email\">Цель для писем</h2>\n<p>Почтовые службы ограничивают вложения, часто до 20 или 25 МБ на письмо. Набор изображений, который должен уместиться в лимит, выигрывает от нестандартных целей.</p>\n<p>Разделите лимит на число изображений, чтобы найти бюджет каждого файла. Десять изображений при общем лимите 20 МБ получают по 2 МБ каждое.</p>\n<p>Для одного изображения лимит редко важен. Одно фото на 500 КБ отправляется легко, а одно на 5 МБ может не пройти.</p>\n<p>Для писем используйте JPG: некоторые почтовые клиенты плохо обрабатывают WebP.</p>\n<p>Проверьте письмо, отправив его сначала себе. Убедитесь, что изображения загружаются быстро и выглядят правильно.</p>\n<h2 id=\"target-for-print-prep\">Цель для подготовки к печати</h2>\n<p>Типографии иногда указывают максимальный вес файла для загрузки. Нестандартная цель попадает в это число ровно, без угадывания.</p>\n<p>Помните, что для печати нужно разрешение, а не только вес файла. Файл на 2 МБ при низком разрешении всё равно печатается плохо, каким бы ни был его вес.</p>\n<p>Для печати используйте оригинал в полном разрешении. Копии для сайта существуют для экрана, а оригинал — для принтера.</p>\n<p>Если типография просит и вес, и разрешение, выполните оба требования. Вес без разрешения — это только половина задачи.</p>\n<p>Проверьте предпросмотр печати, если печатаете страницу с изображением. Фото, хорошее на экране, на бумаге может выглядеть грубо.</p>\n<h2 id=\"comparing-targets\">Сравнение целей</h2>\n<p>Сделайте две копии одного фото с разными целями: например, 100 КБ и 300 КБ. Откройте их рядом в полном размере.</p>\n<p>Смотрите на детали: волосы, ткань, мелкий текст. Отметьте, где разница видна, а где её нет.</p>\n<p>Часто разница между 100 и 300 КБ заметна, а между 300 КБ и 1 МБ — нет. Знание этого экономит трафик.</p>\n<p>Покажите обе версии другу, не говоря, какая какая. Если он не отличит их, разница не стоит дополнительного веса.</p>\n<p>Запишите вывод для своего типа изображений. В следующий раз выбор цели займёт секунды.</p>\n<h2 id=\"saving-presets\">Сохранение настроек</h2>\n<p>Инструмент ничего не запоминает между визитами, поэтому ваш список — это память. Запишите цели, которые используете чаще всего.</p>\n<p>Держите короткую заметку: портал, цель, формат. Например, «портал вакансий — 200 КБ — JPG».</p>\n<p>Добавьте инструмент в закладки. Закладка на компрессор полезнее длинного объяснения теории сжатия.</p>\n<p>Делитесь заметкой с коллегами. Общие настройки избавляют каждого от догадок.</p>\n<p>Обновляйте заметку, когда меняются правила порталов. Прошлогодние цели могут не подойти сегодня.</p>\n<h2 id=\"accessibility-custom\">Доступность при нестандартных целях</h2>\n<p>Сжатое изображение всё равно должно быть понятным. Фото документа должно показывать текст достаточно чётко, чтобы любой проверяющий мог его прочитать.</p>\n<p>Высокий контраст помогает. Объект, выделяющийся на фоне, легче увидеть всем, включая людей со слабым зрением.</p>\n<p>Не полагайтесь только на цвет. Форма, использующая цвет для разделения областей, становится запутанной, когда сжатие приглушает цвета.</p>\n<p>Для изображений в интернете всегда добавляйте описательный alt-текст. Изображение с хорошим alt-текстом служит большему числу людей.</p>\n<p>Сжатие и доступность идут вместе. Чёткий исходник с высоким контрастом сжимается лучше и легче читается каждым зрителем.</p>\n<p>Когда портал впервые просит необычный лимит, не пугайтесь: введите число точно так, как оно написано, и дайте инструменту сделать работу. Нестандартная цель — это обычная задача для этого инструмента.</p>\n<p>Держите под рукой список своих частых целей: 80 КБ для одного портала, 150 КБ для другого, 300 КБ для блога. Список экономит время при каждой подаче.</p>\n<p>Проверяйте результат в байтах, а не в округлённых килобайтах. Портал считает байты, и разница в несколько байтов может решить всё.</p>\n<p>Если цель очень маленькая, обрежьте фото плотнее перед сжатием. Плотный кадр вокруг главного объекта даёт компрессору больше свободы.</p>\n<p>Для командной работы запишите цели в общую заметку. Когда каждый автор вводит цель по-своему, результаты расходятся.</p>\n<p>Не забывайте про формат: WebP при нестандартной цели часто решает, достигнута она или нет. Один тест с двумя форматами стоит больше десяти догадок.</p>\n<p>Когда меняете цель для уже сжатого файла, делайте это с оригинала. Пережимание готовой копии добавляет повреждения без пользы.</p>\n<p>Сохраняйте обе версии, если обе могут понадобиться. Файл на 80 КБ и файл на 100 КБ — это разные файлы для разных порталов.</p>\n<p>И помните: точный размер — это не магия, а поиск. Инструмент проверяет качество шаг за шагом, и ваша задача — задать правильную цель и формат.</p>\n<p>Самая дорогая ошибка в нестандартном сжатии — ошибка единицы измерения. Ввод 100 МБ вместо 100 КБ даёт цель в тысячу раз больше нужной.</p>\n<p>Почтовые службы ограничивают вложения, часто до 20 или 25 МБ на письмо. Разделите лимит на число изображений, чтобы найти бюджет каждого файла.</p>\n<p>Типографии иногда указывают максимальный вес файла для загрузки. Нестандартная цель попадает в это число ровно, без угадывания.</p>\n<p>Сделайте две копии одного фото с разными целями — например, 100 КБ и 300 КБ — и сравните их рядом. Часто разница между ними заметна, а между 300 КБ и 1 МБ — нет.</p>\n<p>Инструмент ничего не запоминает между визитами, поэтому ваш список целей — это память. Запишите цели, которые используете чаще всего.</p>\n<p>Сжатое изображение всё равно должно быть понятным: фото документа должно показывать текст достаточно чётко, чтобы любой проверяющий мог его прочитать.</p>\n<p>Пакетный режим сжимает много изображений до одной нестандартной цели сразу. Каждое изображение обрабатывается отдельно.</p>\n<p>Чек-лист перед вводом цели: число прочитано дважды, единица выбрана верно, формат проверен по правилам портала, размеры в пикселях записаны.</p>\n<p>Практические шаги читайте в статье <a href=\"/ru/blog/kak-szhat-izobrazhenie-do-tochnogo-razmera-v-kb/\">Как сжать изображение до точного размера в КБ</a>. Объяснение поиска — в статье <a href=\"/ru/blog/binarnyy-poisk-kachestva-tochnyy-razmer-v-kb/\">Бинарный поиск качества: точный размер в КБ</a>. Для стандартных лимитов используйте <a href=\"/ru/szhat-izobrazhenie-do-100-kb/\">компрессор до 100 КБ</a> или <a href=\"/ru/szhat-izobrazhenie-do-200-kb/\">компрессор до 200 КБ</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Какой диапазон размеров можно ввести в компрессор до точного размера?","answer":"Любое значение: от нескольких килобайт до нескольких мегабайт. Введите число и выберите КБ или МБ. Помните, что очень маленькие цели — например, 10 КБ для детального фото — могут быть недостижимы без потери смысла изображения."},{"question":"Насколько точен итоговый размер файла по сравнению с моей целью?","answer":"Инструмент целится чуть ниже цели, обычно на несколько килобайт ниже. Порталы проверяют точное число байтов, и небольшой запас защищает от различий в округлении. Файл почти никогда не весит ровно столько, сколько вы ввели, — и это нормально."},{"question":"Можно ли сжать партию фото до одного нестандартного размера?","answer":"Да. Пакетный режим сжимает много изображений до одной цели сразу: перетащите папку, введите цель — и скачайте результаты архивом ZIP. Каждое изображение обрабатывается отдельно, поэтому качество подбирается для каждого файла."},{"question":"Что произойдёт, если загрузить изображение, которое уже меньше моей цели?","answer":"Тогда сжимать его не нужно: файл уже укладывается в цель. Инструмент может всё равно обработать его, но это добавит потери без пользы. Используйте файл как есть, если он выглядит хорошо."},{"question":"Почему инструмент сначала проверяет качество, а потом уменьшает размеры?","answer":"Потому что большинство людей хотят сохранить размеры. Снижение качества при полном размере даёт лучший результат, чем уменьшение размеров. Только когда ни одно качество не укладывается в цель, инструмент пошагово уменьшает размеры."},{"question":"Что лучше: фиксированный инструмент или инструмент с нестандартной целью?","answer":"Фиксированный — когда лимит стандартный: 50, 100, 200 или 500 КБ. Нестандартный — когда портал требует необычное число, например 80 или 150 КБ. Оба используют один и тот же бинарный поиск, разница только в том, кто задаёт цель."}];
